# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">SANAYİ DEVRİMİ: NEDENLER VE ÜRETİM TARZINDAKİ DÖNÜŞÜM</text>\n  <rect x="25" y="48" width="315" height="192" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">İngiltere\'de Başlamasının Nedenleri</text>\n  <text x="40" y="98" font-size="11.5" fill="#1e3a8a">• Zengin taş kömürü ve demir madenleri</text>\n  <text x="40" y="122" font-size="11.5" fill="#1e3a8a">• Sömürge ticaretiyle oluşan sermaye birikimi</text>\n  <text x="40" y="146" font-size="11.5" fill="#1e3a8a">• Çitleme (Enclosure) hareketiyle köyden</text>\n  <text x="48" y="164" font-size="11" fill="#1e3a8a">kente göç eden ucuz iş gücü potansiyeli</text>\n  <text x="40" y="188" font-size="11.5" fill="#1e3a8a">• Bilimsel-teknik icatlar (James Watt - Buhar)</text>\n  <text x="40" y="212" font-size="11.5" fill="#1e3a8a">• Siyasi istikrar ve mülkiyet güvencesi</text>\n\n  <rect x="360" y="48" width="315" height="192" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">Geleneksel Üretimden Fabrikaya Geçiş</text>\n  <rect x="375" y="86" width="285" height="62" rx="6" fill="#ffffff" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="517" y="106" text-anchor="middle" font-size="12" font-weight="bold" fill="#b45309">Geleneksel Zanaat / Lonca Üretimi</text>\n  <text x="517" y="124" text-anchor="middle" font-size="10.5" fill="#78350f">El emeği ve hayvan gücü • Küçük atölye</text>\n  <text x="517" y="140" text-anchor="middle" font-size="10.5" fill="#78350f">Sınırlı ve yavaş üretim • Yüksek birim maliyet</text>\n  <rect x="375" y="160" width="285" height="65" rx="6" fill="#ffffff" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="517" y="180" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">Sanayi Devrimi (Fabrika Sistemi)</text>\n  <text x="517" y="198" text-anchor="middle" font-size="10.5" fill="#14532d">Buhar ve makine gücü • Büyük fabrikalar</text>\n  <text x="517" y="214" text-anchor="middle" font-size="10.5" fill="#14532d">Standart, hızlı, seri ve ucuz kitlesel üretim</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">SANAYİ DEVRİMİ\'NİN SOSYAL, EKONOMİK VE SİYASİ SONUÇLARI</text>\n  <rect x="20" y="50" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.8"/>\n  <text x="125" y="74" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">Ekonomik Sonuçlar</text>\n  <text x="32" y="100" font-size="10.5" fill="#334155">• Seri, standart ve ucuz üretim</text>\n  <text x="32" y="122" font-size="10.5" fill="#334155">• Ham madde ve pazar ihtiyacının</text>\n  <text x="40" y="138" font-size="10.5" fill="#475569">küresel ölçekte artması</text>\n  <text x="32" y="160" font-size="10.5" fill="#334155">• Demiryolu, buharlı gemi ve</text>\n  <text x="40" y="176" font-size="10.5" fill="#475569">bankacılık/finans sisteminin</text>\n  <text x="40" y="192" font-size="10.5" fill="#475569">hızla büyümesi</text>\n  <text x="32" y="214" font-size="10.5" font-weight="bold" fill="#1e40af">• Endüstriyel kapitalizmin doğuşu</text>\n\n  <rect x="245" y="50" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="350" y="74" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">Sosyal ve Çevresel Sonuçlar</text>\n  <text x="257" y="100" font-size="10.5" fill="#334155">• Köyden kente göç ve metropoller</text>\n  <text x="257" y="122" font-size="10.5" fill="#334155">• İşçi sınıfının (proletarya) ve</text>\n  <text x="265" y="138" font-size="10.5" fill="#475569">sendikal hareketlerin doğuşu</text>\n  <text x="257" y="160" font-size="10.5" fill="#334155">• Kadın ve çocuk işçiliği sorunu</text>\n  <text x="257" y="182" font-size="10.5" fill="#334155">• Çekirdek aileye geçiş</text>\n  <text x="257" y="204" font-size="10.5" font-weight="bold" fill="#166534">• Fosil yakıt kullanımıyla çevre</text>\n  <text x="265" y="220" font-size="10.5" font-weight="bold" fill="#166534">ve hava kirliliğinin başlaması</text>\n\n  <rect x="470" y="50" width="210" height="190" rx="8" fill="#fef2f2" stroke="#dc2626" stroke-width="1.8"/>\n  <text x="575" y="74" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#b91c1c">Siyasi ve İdeolojik Sonuçlar</text>\n  <text x="482" y="100" font-size="10.5" fill="#334155">• Burjuvazinin siyasi gücünün</text>\n  <text x="490" y="116" font-size="10.5" fill="#475569">artması</text>\n  <text x="482" y="138" font-size="10.5" fill="#334155">• Kapitalizm, liberalizm ve</text>\n  <text x="490" y="154" font-size="10.5" fill="#475569">sosyalizm akımlarının gelişimi</text>\n  <text x="482" y="176" font-size="10.5" fill="#334155">• Sömürgecilik (emperyalizm)</text>\n  <text x="490" y="192" font-size="10.5" fill="#475569">yarışının hızlanması</text>\n  <text x="482" y="214" font-size="10.5" font-weight="bold" fill="#991b1b">• Küresel bloklaşma ve savaşlar</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">SANAYİ DEVRİMİ\'NİN OSMANLI EKONOMİSİNE ETKİ ZİNCİRİ</text>\n  <rect x="25" y="55" width="145" height="170" rx="8" fill="#dbeafe" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="97" y="80" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">1. Ucuz Mamul Girişi</text>\n  <text x="35" y="105" font-size="10" fill="#334155">• Avrupa\'nın ucuz fabrika</text>\n  <text x="35" y="120" font-size="10" fill="#334155">malları kapitülasyonlar</text>\n  <text x="35" y="135" font-size="10" fill="#334155">ve Balta Limanı (1838)</text>\n  <text x="35" y="150" font-size="10" fill="#334155">ile iç pazara hâkim oldu.</text>\n\n  <rect x="195" y="55" width="145" height="170" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="267" y="80" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#92400e">2. Loncaların Çöküşü</text>\n  <text x="205" y="105" font-size="10" fill="#334155">• El emeğine dayalı</text>\n  <text x="205" y="120" font-size="10" fill="#334155">Osmanlı el tezgâhları</text>\n  <text x="205" y="135" font-size="10" fill="#334155">ve lonca esnafı ucuz</text>\n  <text x="205" y="150" font-size="10" fill="#334155">ithal malla rekabet</text>\n  <text x="205" y="165" font-size="10" fill="#334155">edemeyerek kapandı.</text>\n\n  <rect x="365" y="55" width="145" height="170" rx="8" fill="#fce7f3" stroke="#db2777" stroke-width="1.8"/>\n  <text x="437" y="80" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#9d174d">3. Ham Madde ve Pazar</text>\n  <text x="375" y="105" font-size="10" fill="#334155">• Osmanlı; ham madde</text>\n  <text x="375" y="120" font-size="10" fill="#334155">ihraç eden, mamul mal</text>\n  <text x="375" y="135" font-size="10" fill="#334155">ithal eden açık pazar</text>\n  <text x="375" y="150" font-size="10" fill="#334155">konumuna düştü; dış</text>\n  <text x="375" y="165" font-size="10" fill="#334155">ticaret açığı büyüdü.</text>\n\n  <rect x="535" y="55" width="140" height="170" rx="8" fill="#fef2f2" stroke="#dc2626" stroke-width="1.8"/>\n  <text x="605" y="80" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#991b1b">4. Mali Bağımlılık</text>\n  <text x="545" y="105" font-size="10" fill="#334155">• Dış borçlanma (1854)</text>\n  <text x="545" y="120" font-size="10" fill="#334155">ve Muharrem Kararnamesi</text>\n  <text x="545" y="135" font-size="10" fill="#334155">ile Düyûn-ı Umûmiye</text>\n  <text x="545" y="150" font-size="10" fill="#334155">(1881) kurularak mali</text>\n  <text x="545" y="165" font-size="10" fill="#334155">denetim kaybedildi.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
